        private bool SaveReview()
        {
            SIM_ScheduleChecking obj = new SIM_ScheduleChecking();
            obj.ReviewUser = User.UserName;
            obj.BeginTransaction();

            int? intCount = 0;
            foreach (RepeaterItem item in rptList.Items)
            {
                TextBox txtFlag = item.FindControl("txtFlag") as TextBox;
                if (txtFlag.Text != "") // có sửa
                {
                    CheckBox chk = item.FindControl("chkIsReview") as CheckBox;
                    if (chk.Enabled) // có quyền edit
                    {
                        HiddenField hidID = item.FindControl("hidScheduleCheckingID") as HiddenField;
                        TextBox txtComment = item.FindControl("txtReviewComment") as TextBox;

                        if (hidID.Value != "") // có id sổ đầu bài
                        {
                            obj.ScheduleCheckingID = Convert.ToInt64(hidID.Value);
                            obj.IsReviewed = chk.Checked;
                            obj.ReviewComment = txtComment.Text;
                            if (!obj.UpdateReview())
                            {
                                MsgBox.ShowError("Việc cập nhật duyệt (tổng) bị lỗi! " + obj.ErrorException.Message);
                                return false;
                            }
                            intCount++;
                        }
                    }
                }
            }
            obj.CommitTransaction();
            MsgBox.ShowInfo("Đã cập nhật duyệt thành công! Số dòng: " + intCount);

            // ghi log
            string strActionLog = uClassSubject.YearID.ToString() + " - HK " + uClassSubject.Semester;
            new SystemObject.SYS_ActionLog().WriteActionLog("Duyệt sổ đầu bài", strActionLog, SystemObject.ActionLogType.EDIT, 1, User.UserName);

            return true;
        }

        private void ExportExcel()
        {
            Hashtable hstColumns = new Hashtable();
            Hashtable hstReplaceValues = new Hashtable();
            Hashtable hstSummary = new Hashtable();
            SIM_ScheduleChecking obj = new SIM_ScheduleChecking();

            #region  Lấy classsubject info

            string strSubject_Class = "";
            if (uClassSubject.ClassSubjectID != null)
            {
                DataTable dtb = obj.GetDataTable("SIM_Class_Subject_GetInfo", "@ClassSubjectID", uClassSubject.ClassSubjectID);

                if (dtb == null || dtb.Rows.Count == 0)
                {
                    MsgBox.ShowError("Việc lấy thông tin môn học lớp bị lỗi!");
                    return;
                }

                DataRow drw = dtb.Rows[0];
                hstReplaceValues.Add("{Khoa}", drw["ScienceName"]);
                hstReplaceValues.Add("{Khóa}", drw["CourseName"]);
                //hstReplaceValues.Add("{Ngành}", drw["SpecialBranchName"]);
                hstReplaceValues.Add("{Lớp}", drw["ClassName"]);
                hstReplaceValues.Add("{Môn}", drw["SubjectName"]);
                //hstReplaceValues.Add("{Niên}", drw["YearText"]);
                //hstReplaceValues.Add("{Kì}", drw["Semester"]);
                hstReplaceValues.Add("{Giáo viên}", drw["TeacherName"]); // + "  (Từ ............... đến ...............)");

                hstReplaceValues.Add("{HỌ VÀ TÊN GIÁO VIÊN}", "HỌ VÀ TÊN GIÁO VIÊN: " + drw["TeacherName"]);
                hstReplaceValues.Add("{MÔN HỌC/MÔ - ĐUN}", "MÔN HỌC/MÔ - ĐUN: " + drw["SubjectName"]);

                hstReplaceValues.Add("{Hệ Số Môn}", drw["UnitText"]);
                hstReplaceValues.Add("{LT}", drw["TheoryQuantity"]);
                hstReplaceValues.Add("{TH}", drw["PracticeQuantity"]);
                //hstReplaceValues.Add("{Số Giờ Khung}", drw["TotalQuantity"]);     

                strSubject_Class = WebGlobal.FilterFileName(drw["SubjectName"] + "_" + drw["ClassName"]);

            }

            #endregion

            DataTable dtbExport = obj.GetDataTable("SIM_ScheduleChecking_SearchSummary",
                                        "@YearID", uClassSubject.YearID,
                                        "@Semester", uClassSubject.Semester,
                                        "@ScienceID", uClassSubject.ScienceID,
                                        "@CourseID", uClassSubject.CourseID,
                                        "@ClassID", uClassSubject.ClassID,
                                        "@ClassSubjectID", uClassSubject.ClassSubjectID,
                                        "@FromDate", dtmFromDate.SelectedDate,
                                        "@ToDate", dtmToDate.SelectedDate,
                                        "@LoginName", User.UserName,
                                        "@ManagerTeacherID", User.UserName); // hoặc là chủ nhiệm

            string strPath = System.Web.HttpContext.Current.Server.MapPath("~");

            string strFilePath = strPath + "Template\\Bang ghi tom tat noi dung.xlsx";
            string strFileNameSaveAs = "So len lop_" + (strSubject_Class != "" ? strSubject_Class : User.UserName) + ".xlsx";

            string strPathSaveAs = strPath + "Export\\" + strFileNameSaveAs;

            // tính dòng tổng
            hstSummary.Add("OffStudentCount", 0);

            string[] cols = { "DateText", "TheoryQuantity", "PracticeQuantity", "TestQuantity", "LearningContent", "RequestContent", "OffStudentCount", "OffStudentList", "Rating", "Description" }; //, "EndCol" };

            foreach (string str in cols)
                hstColumns.Add(str, str);

            //if (Libs.Excel.ExportTemplateExcel(dtbExport, strFilePath, "StudentCode", hstColumns, hstReplaceValues, strPathSaveAs))
            if (Libs.CExcel.ExportTemplateExcel(dtbExport, strFilePath, "DateText", hstColumns, hstReplaceValues,hstSummary, strPathSaveAs))
            {
                Response.Redirect("/Export/" + strFileNameSaveAs + "?time=" + DateTime.Now.ToString("yyMMddHHmmss"));
                //Response.Redirect(DCore.Globals.ApplicationVRoot + "/DownloadFile.ashx?key=" + DownloadFile.GenerateKeyForExport(strFileNameSaveAs, User.Username, "Viet$minh"));
            }
            else
            {
                MsgBox.ShowError("Việc xuất excel thất bại");
            }
        }

