            if (bol != null && bol.ToString() != "")
                return Convert.ToBoolean(bol);
            return false;
        }

        protected bool AllowEdit(object teacherIDOfSchedule, object date, object allowEdit, object allowEdit_Rechange, object isReview1, object isReview)
        {
            //if (teacherIDOfSchedule == null || teacherIDOfSchedule.ToString() == "")
            //    return false;

            if (bolIsLocked) // đã khóa sổ điểm
                return false;

            if (IsTrue(isReview1) || IsTrue(isReview)) // đã duyệt sổ hoặc duyệt tổng
                return false;

            if (User == null) // || User.UserName != teacherID.ToString()) // chưa đăng nhập hoặc không phải giáo viên dạy
                return false;

            if (User.UserName.ToLower() == "administrator")
                return true;

            // nếu không có quyền quản lý sửa hộ lại thì kiểm tra giới hạn thời gian + quyền sửa
            if (!IsTrue(allowEdit_Rechange))
            {
                if (this.CheckingExpiredDay != -9999999 && Convert.ToDateTime(date).AddDays(this.CheckingExpiredDay.Value) < DateTime.Now.Date)
                    return false;

                if (this.CheckingNextDay != -9999999 && DateTime.Now.Date.AddDays(this.CheckingNextDay.Value) < Convert.ToDateTime(date))
                    return false;

                if (User.UserName.ToLower() != teacherIDOfSchedule.ToString().ToLower() // không phải của mình                        
                        && !IsTrue(allowEdit) // và cũng ko có quyền sửa
                    )
                    return false; // không có quyền sửa và tkb này cũng không phải của mình thì ko sửa được
            }

            return true;
        }

