        #region Sign CA Functions for Row (popup)

        private void LoadSignCA_Popup(long? classSubjectID, string teacherID_Schedule, DateTime date, int session)
        {
            #region Lấy thông tin môn học lớp đang xét

            SimsObject.SIM_Area obj = new SIM_Area();
            DataTable dtb = obj.GetDataTable("SIM_Class_Subject_GetInfo", "@ClassSubjectID", classSubjectID);
            if (dtb == null || dtb.Rows.Count == 0)
            {
                MsgBox.ShowError("Việc lấy thông tin môn học lớp bị lỗi!<br>" + obj.ErrorException.Message);
                lblTeacher.Text = "";
                return;
            }

            DataRow drw = dtb.Rows[0];

            string strScienceManager_Subject = drw["ScienceManager_Subject"].ToString().ToLower(); // khoa của bộ môn
            string strScienceManager_Subject2 = drw["ScienceManager_Subject2"].ToString().ToLower(); // phó 1
            string strScienceManager_Subject3 = drw["ScienceManager_Subject3"].ToString().ToLower(); // phó 2

            #endregion

            // Bắt đầu như bên List

            string strTeacher = !string.IsNullOrWhiteSpace(teacherID_Schedule) ? "_" + teacherID_Schedule : ""; // có gv dạy thì seri thêm mã gv dạy

            uSignArea_Popup.DocFormID = "ScheduleChecking_ContentFile"; // Tập tin giáo án đính kèm theo từng Row (gv tkb, ngày, buổi)
            if (classSubjectID != null) // Mã môn học lớp + Mã gv giảng dạy (nếu có)
                uSignArea_Popup.DocSerial = classSubjectID + strTeacher + "_" + date.ToString("yyyyMMdd") + "_" + session;

            // Ds người ký: GiaoVien, KhoaBoMon, PĐT
            Hashtable hstSigner = new Hashtable();
            hstSigner.Add("GiaoVienGiangDay", teacherID_Schedule); // gv giảng dạy theo tkb (không phải pc nhập điểm trong môn học lớp)
            //hstSigner.Add("GiaoVien", this.TeachingBy); // gv phân công trong môn học lớp (nếu có)

            // KhoaBoMon: vị trí này có 3 người có thể ký nên mình trùng tên mình thì ưu tiên sẽ là mình ký nếu chưa ai ký
            if (strScienceManager_Subject == User.UserName.ToLower()) // nếu mình là trưởng khoa thì ưu tiên ký vô vị trí KhoaBoMon
                hstSigner.Add("KhoaBoMon", strScienceManager_Subject);

            else if (strScienceManager_Subject2 == User.UserName.ToLower()) // nếu mình là phó 1 thì ký vô vị trí KhoaBoMon
                hstSigner.Add("KhoaBoMon", strScienceManager_Subject2);

            else if (strScienceManager_Subject3 == User.UserName.ToLower()) // nếu mình là phó 2 thì ký vô vị trí KhoaBoMon
                hstSigner.Add("KhoaBoMon", strScienceManager_Subject3);

            else
                hstSigner.Add("KhoaBoMon", strScienceManager_Subject); // mặc định là trưởng khoa nếu mình ko có tên nào trùng

            uSignArea_Popup.SignerList = hstSigner;

            uSignArea_Popup.LoadData();

            // chưa rõ xử lý sao, để sau
            //if (uSignArea_Popup.IsLockingDoc)
            //{
            //    btnCopyFromTeachingSchedule.Visible = false; // ẩn nút lưu do dữ liệu đã ký hoặc đang chờ ký
            //    bolIsLockingDoc = true; // do khóa số
            //}
        }

