        protected void lbtViewSignCA_Click(object sender, EventArgs e)
        {
            LinkButton lbt = sender as LinkButton;

            int intIndex = Convert.ToInt32(lbt.ToolTip);
            RepeaterItem rptItem = rptList.Items[intIndex];

            HiddenField hidCSID = rptItem.FindControl("hidClassSubjectID") as HiddenField;
            HiddenField hidTeacherIDOfSchedule = rptItem.FindControl("hidTeacherIDOfSchedule") as HiddenField;
            LinkButton lbtEdit = rptItem.FindControl("lbtEdit") as LinkButton;

            long? lngCSID = Convert.ToInt64(hidCSID.Value);
            string strTeacherID = hidTeacherIDOfSchedule.Value; // giáo viên của lịch  
            DateTime dtmDate = Convert.ToDateTime(lbt.CommandName);
            int intSessionID = Convert.ToInt32(lbt.CommandArgument);

            uSignArea_Popup.AllowEditFile = lbtEdit != null && lbtEdit.Visible && uEdit.AllowUploadFile(dtmDate); // có quyền sửa sổ lên lớp + còn hạn upload file

            LoadSignCA_Popup(lngCSID, strTeacherID, dtmDate, intSessionID); // khác tổng ở chỗ có gv, ngày, buổi theo từng dòng TKB
            uSignArea_Popup.ShowPopup();
        }

