                HiddenField hidWeek = rptItem.FindControl("hidWeek") as HiddenField;
                HiddenField hidClassSubjectID = rptItem.FindControl("hidClassSubjectID") as HiddenField;

                uEdit.ClassSubjectID = Convert.ToInt64(hidClassSubjectID.Value);
                uEdit.Date = Convert.ToDateTime(lbt.CommandName);
                uEdit.SessionID = Convert.ToInt32(hidSession.Value);
                uEdit.TeacherID = hidTeacherIDOfSchedule.Value; // giáo viên của lịch  

