        // Tên file và thư mục con theo bản mới
        protected string GetSubUrl(object contentFile, object subjectID, object classID)
        {
            return uClassSubject.YearID + "_" + uClassSubject.Semester + "/" + subjectID + "/" + classID + "/" + contentFile; // tập tin kèm thư mục con sau khi chuyển đổi bản mới
        }

        protected bool ModifyUrl()
        {
            if (uClassSubject.YearID == null || uClassSubject.Semester == null) // ko chọn nhiên kỳ thì ko hiệu chỉnh vì sẽ ko đúng
                return false;

            // Đường dẫn bản cũ
            string strFilePath_Physical_OldVersion = DCore.Globals.GetConfig("PhysicalDirectory_Upload") + "\\Data\\ScheduleChecking\\";

            // Đường dẫn Root bản mới
            string strRoot_Physical = DCore.Globals.GetConfig("PhysicalDirectory_Upload") + "\\Data\\ScheduleChecking\\"
                            + uClassSubject.YearID + "_" + uClassSubject.Semester + "\\";

            int intOld = 0;
            int intNew = 0;

            foreach (DataRow drw in dtbData.Rows)
            {
                string contentFile = drw["ContentFile"].ToString();

                if (contentFile.ToString() != "")
                {

                    string subjectID = drw["SubjectID"].ToString();
                    string classID = drw["ClassID"].ToString();

                    // bản mới
                    string strFilePath_Physical = strRoot_Physical + subjectID + "\\" + classID + "\\";  // tạo lại trước khi show (thư mục lưu file)

                    // bản mới có rồi thì bỏ qua
                    if (System.IO.File.Exists(strFilePath_Physical + contentFile))
                    {
                        intNew++;
                        continue;
                    }

                    // file mới ko có thì theo thư mục file cũ thử (nếu có thì chép qua thư mục mới)
                    else if (System.IO.File.Exists(strFilePath_Physical_OldVersion + contentFile))
                    {
                        System.IO.Directory.CreateDirectory(strFilePath_Physical); // Tạo thư mục nếu chưa có                
                        System.IO.File.Move(strFilePath_Physical_OldVersion + contentFile, strFilePath_Physical + contentFile); // di chuyển qua thư mục phiên bản mới

                        intOld++;
                    }

                    else // MR VIỆT 2026.05.12 thêm trường hợp nhầm lẫn do List đã modify sai thư mục về lớp gốc thay gì lớp tách
                    {
                        string classID_Origin = drw["ClassID_Origin"].ToString();
                        string strFilePath_Physical_Missed = strRoot_Physical + subjectID + "\\" + classID_Origin + "\\";

                        if (System.IO.File.Exists(strFilePath_Physical_Missed + contentFile))
                        {
                            System.IO.Directory.CreateDirectory(strFilePath_Physical); // Tạo thư mục nếu chưa có                
                            System.IO.File.Move(strFilePath_Physical_Missed + contentFile, strFilePath_Physical + contentFile); // di chuyển qua thư mục phiên bản mới

                            intOld++;
                        }
                    }
                }
            }

            if (Request["debug"] != null && Request["debug"].ToString() == "1")
            {
                MsgBox.ShowInfo("Đã hiệu chỉnh lưu trữ sổ lên lớp thành công! Số tập tin giữ nguyên: " + intNew + ", số tập tin hiệu chỉnh: " + intOld);
            }
            return true;
        }
    }
}
